window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[46]={"4600":{"example:4600:exzh":"She had a good upbringing."},"4601":{"example:4601:exzh":"I ate a donut for breakfast.","grammar:4601:ex:trans":"I ate a doughnut for breakfast.","grammar:4601:ex:structure":"timeに＋nounを＋食べた。「朝食に」＝at breakfast.","grammar:4601:ex:explain":"「に」 in 「朝食に」 marks a time or occasion, meaning “at breakfast,” following the same pattern as 「夕食に」 and 「昼食に」. The object takes 「を」, and 「食べた」 is the past tense in the plain form, made by removing 「る」 from a lower ichidan verb and adding 「た」. Note that 「朝食」 is more formal or written; 「朝ごはん」 is used in everyday conversation. 「ドーナツ」 is a loanword from the English “doughnut,” and is also sometimes written 「ドーナッツ」.","grammar:4601:ex:words:0:zh":"breakfast","grammar:4601:ex:words:0:note":"ちょうしょく","grammar:4601:ex:words:0:pos":"noun","grammar:4601:ex:words:1:zh":"(point in time)","grammar:4601:ex:words:1:pos":"particle","grammar:4601:ex:words:2:zh":"doughnut","grammar:4601:ex:words:2:note":"Loanword: donut","grammar:4601:ex:words:2:pos":"noun","grammar:4601:ex:words:3:zh":"(object marker)","grammar:4601:ex:words:3:pos":"particle","grammar:4601:ex:words:4:zh":"ate","grammar:4601:ex:words:4:note":"たべた; ta-form","grammar:4601:ex:words:4:pos":"verb","grammar:4601:ex:points:0":"〜に：at … (a point in time; 朝食に＝at breakfast)","grammar:4601:ex:points:1":"ドーナツ：doughnut"},"4602":{"example:4602:exzh":"The weather today is so-so."},"4603":{"example:4603:exzh":"His path is to become a doctor.","example:4603:exzh2":"Choosing a career path is important.","example:4603:exzh3":"My path for university has been decided.","example:4603:exzh4":"Let's discuss our career paths.","example:4603:exzh5":"She's good at thinking about her career path."},"4604":{"example:4604:exzh":"During disasters, supplies are often scarce.","example:4604:exzh2":"Supplies were distributed.","example:4604:exzh3":"This area has plenty of supplies.","example:4604:exzh4":"There is a great need for international supplies.","example:4604:exzh5":"We must use supplies wisely."},"4605":{"example:4605:exzh":"Once the basics are solid, you can apply them freely.","example:4605:exzh2":"You can learn the basics of math from this book.","example:4605:exzh3":"Let's start over from the basics.","example:4605:exzh4":"The basics are very important.","example:4605:exzh5":"Let's solidify the basics first."},"4606":{"example:4606:exzh":"We have to wait patiently.","example:4606:exzh2":"She is a very patient person.","example:4606:exzh3":"Perseverance is important.","example:4606:exzh4":"Sometimes patience is needed.","example:4606:exzh5":"Let's keep patiently chasing our dreams."},"4607":{"example:4607:exzh":"He often gasps for breath when he's tired.","example:4607:exzh2":"I ran while gasping for breath.","example:4607:exzh3":"I heard gasping.","example:4607:exzh4":"The gasping is caused by a lack of exercise.","example:4607:exzh5":"The gasping has gotten worse."},"4608":{"example:4608:exzh":"I go for a walk to clear my head.","example:4608:exzh2":"I feel like I need something to take my mind off things.","example:4608:exzh3":"He goes to see a movie to unwind.","example:4608:exzh4":"I went traveling for a change of pace.","example:4608:exzh5":"A change of pace is good for mental health."},"4609":{"example:4609:exzh":"Let's stop here.","example:4609:exzh2":"It stopped suddenly.","example:4609:exzh3":"A bird perched on the tree branch.","example:4609:exzh4":"The bus stops in front of the station.","example:4609:exzh5":"The clock has stopped.","grammar:4609:ex:trans":"Let's stop here.","grammar:4609:ex:structure":"ここで止まることにしましょう","grammar:4609:ex:explain":"The core is 「〜ことにする」, which means to decide (oneself) to do something. First 「止まる」 is nominalized with 「こと」, then 「にする」 is added to mean decide; the ending 「しましょう」 is the volitional invitation form, so the whole sentence means let's go ahead and stop here. Note that 「止まる」 is intransitive (it stops by itself), and its transitive counterpart is 「止める」 (to make something stop); here the subject stops itself, so 「止まる」 is used. The location takes 「で」, which marks where the action takes place.","grammar:4609:ex:words:0:zh":"here","grammar:4609:ex:words:0:pos":"pronoun","grammar:4609:ex:words:1:zh":"(place)","grammar:4609:ex:words:1:pos":"particle","grammar:4609:ex:words:2:zh":"to stop","grammar:4609:ex:words:2:note":"とまる","grammar:4609:ex:words:2:pos":"verb","grammar:4609:ex:words:3:zh":"(nominalizer)","grammar:4609:ex:words:3:pos":"noun","grammar:4609:ex:words:4:zh":"(result)","grammar:4609:ex:words:4:pos":"particle","grammar:4609:ex:words:5:zh":"let's decide","grammar:4609:ex:words:5:pos":"verb","grammar:4609:ex:points:0":"❗止まる（とまる）: to stop, to come to a halt, to stay (intransitive verb); vs. 「止める（とめる）」 = to (actively) make something stop, transitive. ここで止まる = to stop here.","grammar:4609:ex:points:1":"止まる: to stop (intransitive) / 止める (transitive).","grammar:4609:ex2:trans":"It stopped suddenly.","grammar:4609:ex2:structure":"急に止まった","grammar:4609:ex2:words:0:zh":"suddenly","grammar:4609:ex2:words:0:note":"きゅうに","grammar:4609:ex2:words:0:pos":"adverb","grammar:4609:ex2:words:1:zh":"to stop","grammar:4609:ex2:words:1:note":"とまった","grammar:4609:ex2:words:1:pos":"verb","grammar:4609:ex2:points:0":"❗急に止まる: to stop abruptly, to stop short.","grammar:4609:ex2:points:1":"急に止まる: to stop short.","grammar:4609:ex3:trans":"A bird perched on a tree branch.","grammar:4609:ex3:structure":"noun が＋place に＋止まった","grammar:4609:ex3:words:0:zh":"bird","grammar:4609:ex3:words:0:note":"とり; bird","grammar:4609:ex3:words:0:pos":"noun","grammar:4609:ex3:words:1:zh":"subject","grammar:4609:ex3:words:1:pos":"particle","grammar:4609:ex3:words:2:zh":"tree","grammar:4609:ex3:words:2:note":"き; tree","grammar:4609:ex3:words:2:pos":"noun","grammar:4609:ex3:words:3:zh":"links nouns","grammar:4609:ex3:words:3:pos":"particle","grammar:4609:ex3:words:4:zh":"tree branch","grammar:4609:ex3:words:4:note":"えだ; tree branch","grammar:4609:ex3:words:4:pos":"noun","grammar:4609:ex3:words:5:zh":"perching spot","grammar:4609:ex3:words:5:pos":"particle","grammar:4609:ex3:words:6:zh":"to stop; to stay","grammar:4609:ex3:words:6:note":"とまっ; first half of the te-form","grammar:4609:ex3:words:6:pos":"verb","grammar:4609:ex3:words:7:zh":"the past","grammar:4609:ex3:words:7:pos":"auxiliary verb","grammar:4609:ex3:points:0":"「止まった」 indicates that the bird stayed at a certain place.","grammar:4609:ex3:points:1":"In 「木の枝に」, the 「に」 marks the place where it stayed.","grammar:4609:ex3:points:2":"「鳥が」 is the one doing the perching; this is a simple, clear N5 pattern.","grammar:4609:ex4:trans":"The bus stops in front of the station.","grammar:4609:ex4:structure":"topic は＋place で＋止まります","grammar:4609:ex4:words:0:zh":"bus","grammar:4609:ex4:words:0:pos":"noun","grammar:4609:ex4:words:1:zh":"marks the topic","grammar:4609:ex4:words:1:pos":"particle","grammar:4609:ex4:words:2:zh":"station","grammar:4609:ex4:words:2:note":"えき; a place where you catch trains","grammar:4609:ex4:words:2:pos":"noun","grammar:4609:ex4:words:3:zh":"links nouns","grammar:4609:ex4:words:3:pos":"particle","grammar:4609:ex4:words:4:zh":"front","grammar:4609:ex4:words:4:note":"まえ; front","grammar:4609:ex4:words:4:pos":"noun","grammar:4609:ex4:words:5:zh":"spot","grammar:4609:ex4:words:5:pos":"particle","grammar:4609:ex4:words:6:zh":"stop","grammar:4609:ex4:words:6:note":"とまり; masu-form stem","grammar:4609:ex4:words:6:pos":"verb","grammar:4609:ex4:words:7:zh":"polite","grammar:4609:ex4:words:7:pos":"auxiliary verb","grammar:4609:ex4:points:0":"「止まります」 means a vehicle stops.","grammar:4609:ex4:points:1":"In 「駅の前で」, the 「で」 marks where the action happens.","grammar:4609:ex4:points:2":"「バスは」 first announces that the sentence is about the bus.","grammar:4609:ex5:trans":"The clock has stopped.","grammar:4609:ex5:structure":"noun が＋止まっています","grammar:4609:ex5:words:0:zh":"clock","grammar:4609:ex5:words:0:note":"とけい; clock","grammar:4609:ex5:words:0:pos":"noun","grammar:4609:ex5:words:1:zh":"subject","grammar:4609:ex5:words:1:pos":"particle","grammar:4609:ex5:words:2:zh":"stop","grammar:4609:ex5:words:2:note":"とまっ; first half of the te-form","grammar:4609:ex5:words:2:pos":"verb","grammar:4609:ex5:words:3:zh":"links","grammar:4609:ex5:words:3:pos":"particle","grammar:4609:ex5:words:4:zh":"a continuing state","grammar:4609:ex5:words:4:pos":"auxiliary verb","grammar:4609:ex5:words:5:zh":"polite","grammar:4609:ex5:words:5:pos":"auxiliary verb","grammar:4609:ex5:points:0":"「時計が止まっています」 means the clock has stopped and is no longer running; 「止まる」 is also used for machines that stop working.","grammar:4609:ex5:points:1":"The ている in 「止まっています」 shows that the state after stopping keeps going; it does not mean it is in the middle of stopping.","exam:4609:zh":"This bus stops before the next station, so let's get off there.","exam:4609:why":"For a bus stopping to let people get off, you use 「止まる」. 「登る」 means moving to a higher place, so it can't express stopping."},"4610":{"example:4610:exzh":"Most people agreed.","example:4610:exzh2":"It was a largely successful project.","example:4610:exzh3":"Most people took part in today's event.","example:4610:exzh4":"Most of this problem is easy.","example:4610:exzh5":"I spent most of my time on movies."},"4611":{"example:4611:exzh":"When you climb these stairs, the view is beautiful.","example:4611:exzh2":"The last paragraph of the document is important.","example:4611:exzh3":"He pays attention to every paragraph.","example:4611:exzh4":"Please tell me what this paragraph means.","example:4611:exzh5":"Please move on to the next paragraph."},"4612":{"example:4612:exzh":"This painting seems to have a magical power.","example:4612:exzh2":"He was captivated by its magic.","example:4612:exzh3":"Chanted a spell with powerful magic.","example:4612:exzh4":"She used her magical power to solve the problem.","example:4612:exzh5":"That book holds magical power."},"4614":{"example:4614:exzh":"I like eating apples.","example:4614:exzh2":"This apple is very sweet.","example:4614:exzh3":"I drink apple juice every morning.","example:4614:exzh4":"He picked an apple from the tree.","example:4614:exzh5":"Please peel the apple.","grammar:4614:ex:trans":"I like eating apples.","grammar:4614:ex:structure":"〔リンゴを食べる＋の〕＋が＋好きです。","grammar:4614:ex:explain":"The key pattern is 「〜のが好きだ」, meaning “like doing something.” To express liking an action, first nominalize the verb 「食べる」 with the formal noun 「の」, making 「食べるの」 mean “the act of eating.” Then use 「が」 to mark what is liked, followed by 「好きです」. Note that 「好き」 is a な-adjective, and what is liked is normally marked with 「が」 rather than 「を」. Within 「リンゴを食べる」, apples are the object being eaten and are marked with 「を」. The whole sentence means “I like eating apples.”","grammar:4614:ex:words:0:zh":"apple","grammar:4614:ex:words:0:note":"katakana","grammar:4614:ex:words:0:pos":"noun","grammar:4614:ex:words:1:zh":"(object marker)","grammar:4614:ex:words:1:pos":"particle","grammar:4614:ex:words:2:zh":"eat","grammar:4614:ex:words:2:note":"たべる","grammar:4614:ex:words:2:pos":"verb","grammar:4614:ex:words:3:zh":"(nominalizer)","grammar:4614:ex:words:3:pos":"particle","grammar:4614:ex:words:4:zh":"(object marker)","grammar:4614:ex:words:4:pos":"particle","grammar:4614:ex:words:5:zh":"to like","grammar:4614:ex:words:5:note":"すき","grammar:4614:ex:words:5:pos":"na-adjective","grammar:4614:ex:words:6:zh":"(polite form)","grammar:4614:ex:words:6:pos":"copula","grammar:4614:ex:points:0":"verb + の + が好き: like doing…","grammar:4614:ex:points:1":"リンゴ: apple","grammar:4614:ex2:trans":"This apple is very sweet.","grammar:4614:ex2:structure":"この＋noun＋は＋とても＋い-adjective＋です。","grammar:4614:ex2:words:0:zh":"this","grammar:4614:ex2:words:0:pos":"pre-noun adjectival","grammar:4614:ex2:words:1:zh":"apple","grammar:4614:ex2:words:1:note":"katakana","grammar:4614:ex2:words:1:pos":"noun","grammar:4614:ex2:words:2:zh":"(topic marker)","grammar:4614:ex2:words:2:pos":"particle","grammar:4614:ex2:words:3:zh":"extremely","grammar:4614:ex2:words:3:pos":"adverb","grammar:4614:ex2:words:4:zh":"sweet","grammar:4614:ex2:words:4:note":"あまい","grammar:4614:ex2:words:4:pos":"adjective","grammar:4614:ex2:words:5:zh":"(polite form)","grammar:4614:ex2:words:5:pos":"copula","grammar:4614:ex2:points:0":"甘い: sweet","grammar:4614:ex2:points:1":"このリンゴ: this apple","grammar:4614:ex3:trans":"I drink apple juice every morning.","grammar:4614:ex3:structure":"time, nounを＋飲みます. 「毎朝」 shows a habit.","grammar:4614:ex3:words:0:zh":"every morning","grammar:4614:ex3:words:0:note":"まいあさ","grammar:4614:ex3:words:0:pos":"noun","grammar:4614:ex3:words:1:zh":"Apple juice","grammar:4614:ex3:words:1:note":"loanword","grammar:4614:ex3:words:1:pos":"noun","grammar:4614:ex3:words:2:zh":"(object marker)","grammar:4614:ex3:words:2:pos":"particle","grammar:4614:ex3:words:3:zh":"to drink","grammar:4614:ex3:words:3:note":"のみます","grammar:4614:ex3:words:3:pos":"verb","grammar:4614:ex3:points:0":"毎朝: every morning","grammar:4614:ex3:points:1":"リンゴジュース: apple juice","grammar:4614:ex4:trans":"He picked an apple from the tree.","grammar:4614:ex4:structure":"〜は＋nounを＋place＋から＋摘みました。「〜から摘む」＝pick from….","grammar:4614:ex4:words:0:zh":"he","grammar:4614:ex4:words:0:note":"かれ","grammar:4614:ex4:words:0:pos":"pronoun","grammar:4614:ex4:words:1:zh":"(topic marker)","grammar:4614:ex4:words:1:pos":"particle","grammar:4614:ex4:words:2:zh":"apple","grammar:4614:ex4:words:2:note":"katakana","grammar:4614:ex4:words:2:pos":"noun","grammar:4614:ex4:words:3:zh":"(object marker)","grammar:4614:ex4:words:3:pos":"particle","grammar:4614:ex4:words:4:zh":"tree","grammar:4614:ex4:words:4:note":"き","grammar:4614:ex4:words:4:pos":"noun","grammar:4614:ex4:words:5:zh":"from","grammar:4614:ex4:words:5:note":"starting point","grammar:4614:ex4:words:5:pos":"particle","grammar:4614:ex4:words:6:zh":"Picked","grammar:4614:ex4:words:6:note":"つみました","grammar:4614:ex4:words:6:pos":"verb","grammar:4614:ex4:points:0":"〜から: from… (the starting point; 木から＝from the tree)","grammar:4614:ex4:points:1":"摘む: pick, gather","grammar:4614:ex5:trans":"Please peel the apple.","grammar:4614:ex5:structure":"〔リンゴの皮〕＋を＋むいてください。「皮をむく」＝peel.","grammar:4614:ex5:words:0:zh":"apple","grammar:4614:ex5:words:0:note":"katakana","grammar:4614:ex5:words:0:pos":"noun","grammar:4614:ex5:words:1:zh":"'s","grammar:4614:ex5:words:1:pos":"particle","grammar:4614:ex5:words:2:zh":"skin","grammar:4614:ex5:words:2:note":"かわ","grammar:4614:ex5:words:2:pos":"noun","grammar:4614:ex5:words:3:zh":"(object marker)","grammar:4614:ex5:words:3:pos":"particle","grammar:4614:ex5:words:4:zh":"Peel","grammar:4614:ex5:words:4:note":"皮をむく＝peel; te-form","grammar:4614:ex5:words:4:pos":"verb","grammar:4614:ex5:words:5:zh":"please","grammar:4614:ex5:words:5:note":"〜てください","grammar:4614:ex5:words:5:pos":"verb","grammar:4614:ex5:points:0":"皮をむく: peel, remove the skin","grammar:4614:ex5:points:1":"リンゴの皮: apple skin","exam:4614:zh":"I bought a round apple with red skin at the fruit shop.","exam:4614:why":"The clues of red skin and a round shape point to 「リンゴ」. 「ミカン」 is round too, but its peel is usually orange."},"4615":{"example:4615:exzh":"Because the documents were late, the submission deadline was extended.","example:4615:exzh2":"The trains stopped because there was an accident.","example:4615:exzh3":"Because of his efforts, we succeeded.","example:4615:exzh4":"Because of the bad weather, the flight was canceled.","example:4615:exzh5":"Because I was late, I was scolded by the teacher."},"4616":{"example:4616:exzh":"He is a motorcycle rider.","example:4616:exzh2":"The riders competed.","example:4616:exzh3":"A new rider joined the team.","example:4616:exzh4":"Special gear for riders is required.","example:4616:exzh5":"He is known as an excellent rider."},"4617":{"example:4617:exzh":"He is working hard to gain fame.","example:4617:exzh2":"Fame is sometimes important.","example:4617:exzh3":"Her fame spread quickly.","example:4617:exzh4":"I act carefully in order to protect my reputation.","example:4617:exzh5":"Fame attracts people."},"4618":{"example:4618:exzh":"I put the baby down to sleep and take a short rest.","example:4618:exzh2":"After getting the dog to lie down, I went for a walk.","example:4618:exzh3":"Because he's tired, I want to get him to bed early.","example:4618:exzh4":"Getting a child to sleep is tough.","example:4618:exzh5":"She lets them sleep late every night."},"4619":{"example:4619:exzh":"Out of pity, I helped that person.","example:4619:exzh2":"I'm drawn to his compassionate nature.","example:4619:exzh3":"Please don't forget compassion.","example:4619:exzh4":"People should treat others with compassion.","example:4619:exzh5":"He was happy to have been shown compassion."},"4620":{"example:4620:exzh":"Chappy is my pet.","example:4620:exzh2":"She is as cute as Chappy.","example:4620:exzh3":"I take Chappy for a walk.","example:4620:exzh4":"Chappy's name is very cute.","example:4620:exzh5":"A friend was happy to see Chappy."},"4621":{"example:4621:exzh":"I learned many lessons from this experience.","example:4621:exzh2":"Lessons from parents are very important.","example:4621:exzh3":"Please don't forget the lesson learned from his failure.","example:4621:exzh4":"This lesson will be useful in our lives.","example:4621:exzh5":"It is important to learn lessons from history."},"4622":{"example:4622:exzh":"He joined a hostile group.","example:4622:exzh2":"Let's think about how to resolve the hostile relationship.","example:4622:exzh3":"This issue could cause hostility.","example:4622:exzh4":"A hostile attitude is not good.","example:4622:exzh5":"We need to cooperate without being hostile."},"4623":{"example:4623:exzh":"I learned how to embed data.","example:4623:exzh2":"He embedded the image in a web page.","example:4623:exzh3":"It's important to embed the necessary information.","example:4623:exzh4":"This program has many features and can embed data easily.","example:4623:exzh5":"Embedding a video in a website is easy."},"4624":{"example:4624:exzh":"The meaning of this word is important.","example:4624:exzh2":"His actions have deep significance.","example:4624:exzh3":"It's important to think about the meaning of life.","example:4624:exzh4":"I understood the significance of this project.","example:4624:exzh5":"The students are learning about the significance of academic study."},"4625":{"example:4625:exzh":"Brainwashing is a dangerous technique.","example:4625:exzh2":"He feels that he was brainwashed.","example:4625:exzh3":"There are groups that use brainwashing techniques.","example:4625:exzh4":"I want to know how to escape brainwashing.","example:4625:exzh5":"This movie is about brainwashing."},"4626":{"example:4626:exzh":"This accident was a big blow to us.","example:4626:exzh2":"After being hit hard, he went to see a doctor.","example:4626:exzh3":"An incident occurred that dealt a blow to the economy.","example:4626:exzh4":"It's difficult to get over a psychological blow.","example:4626:exzh5":"He is trying to forget the blow from the past."},"4627":{"example:4627:exzh":"He turned himself in after committing a crime.","example:4627:exzh2":"Turning yourself in is an act of courage.","example:4627:exzh3":"The police are urging people to turn themselves in.","example:4627:exzh4":"She turned herself in and admitted her guilt.","example:4627:exzh5":"If you turn yourself in, you may receive a lighter punishment."},"4628":{"example:4628:exzh":"He rushed to the scene immediately.","example:4628:exzh2":"I'll rush over for help.","example:4628:exzh3":"We need to hurry over right away.","example:4628:exzh4":"When I heard about the accident, I rushed to the scene.","example:4628:exzh5":"She rushed to the party."},"4629":{"example:4629:exzh":"I shut down the computer.","example:4629:exzh2":"Please check the shutdown procedure.","example:4629:exzh3":"He safely shut down the server.","example:4629:exzh4":"Please save before shutting down.","example:4629:exzh5":"This app shuts down automatically."},"4630":{"example:4630:exzh":"I installed the latest version of this software.","example:4630:exzh2":"The version needs to be updated.","example:4630:exzh3":"The old version can't handle it.","example:4630:exzh4":"Version control is important.","example:4630:exzh5":"The new version's features have been added."},"4631":{"example:4631:exzh":"He received a scholarship.","example:4631:exzh2":"The scholarship system is very important.","example:4631:exzh3":"Please tell me how to apply for a scholarship.","example:4631:exzh4":"Many students are receiving scholarships.","example:4631:exzh5":"Don't miss the chance for a scholarship."},"4632":{"example:4632:exzh":"This GPS is easy to use.","example:4632:exzh2":"The GPS told me the destination.","example:4632:exzh3":"I drive by relying on the GPS.","example:4632:exzh4":"The old GPS is no longer useful.","example:4632:exzh5":"I plan to buy a new GPS."},"4633":{"example:4633:exzh":"The ink ran out.","example:4633:exzh2":"I've got to buy some new ink.","example:4633:exzh3":"The ink in this pen is smudging.","example:4633:exzh4":"The ink color is very pretty.","example:4633:exzh5":"The ink needs to be replaced."},"4634":{"example:4634:exzh":"The subsidy was paid out.","example:4634:exzh2":"Financial assistance is needed.","example:4634:exzh3":"This program is receiving a subsidy.","example:4634:exzh4":"Applying for the subsidy is easy.","example:4634:exzh5":"He is helping with the supporting work."},"4635":{"example:4635:exzh":"I'll get breakfast ready.","example:4635:exzh2":"Are you ready?","example:4635:exzh3":"I have to get ready for the trip.","example:4635:exzh4":"Getting ready takes time.","example:4635:exzh5":"I'll help get ready for the party."},"4636":{"example:4636:exzh":"I can't tell him and her apart.","example:4636:exzh2":"It's hard to tell these colors apart.","example:4636:exzh3":"It's important to understand cultural distinctions.","example:4636:exzh4":"Age distinctions are necessary.","example:4636:exzh5":"It's important to make distinctions."},"4637":{"example:4637:exzh":"His coffin was beautifully decorated.","example:4637:exzh2":"I placed flowers on the coffin.","example:4637:exzh3":"The old coffin has historical value.","example:4637:exzh4":"Carrying a coffin is hard work.","example:4637:exzh5":"There is something important inside the coffin."},"4638":{"example:4638:exzh":"Her appearance is very beautiful.","example:4638:exzh2":"Appearance is not important.","example:4638:exzh3":"What is inside matters more than appearance.","example:4638:exzh4":"There are people with all kinds of appearances.","example:4638:exzh5":"He looks younger than his age."},"4639":{"example:4639:exzh":"Many different ethnic groups coexist.","example:4639:exzh2":"She is proud of her ethnicity.","example:4639:exzh3":"It is important to respect differences between ethnic groups.","example:4639:exzh4":"Many ethnic groups live in this region.","example:4639:exzh5":"Please value your ethnic identity."},"4640":{"example:4640:exzh":"Let's go quickly.","grammar:4640:ex:trans":"Let’s get going quickly.","grammar:4640:ex:structure":"〔早く〕＋行きましょう。「早く」 is the continuative form of 「早い」, used as an adverb meaning “quickly.” 「〜ましょう」＝let’s….","grammar:4640:ex:explain":"This sentence practices using the continuative form of an い-adjective as an adverb. 「早く」 is the continuative form of the adjective 「早い」, formed by replacing い with く. Here it modifies the verb as an adverb meaning “quickly” or “early.” 「行きましょう」 is the volitional invitation form of 「行く」, using 「〜ましょう」 to mean “let’s….” The whole sentence means “Let’s get going quickly.” The key points are remembering the rule for turning an い-adjective into an adverb (い→く) and the way 「ましょう」 suggests or invites someone to act together.","grammar:4640:ex:words:0:zh":"quickly","grammar:4640:ex:words:0:note":"はやく; continuative form of an い-adjective used as an adverb","grammar:4640:ex:words:0:pos":"adverb","grammar:4640:ex:words:1:zh":"let's go","grammar:4640:ex:words:1:note":"いきましょう; ましょう for suggestions","grammar:4640:ex:words:1:pos":"verb","grammar:4640:ex:points:0":"Continuative form of an い-adjective used as an adverb: 早く (quickly)","grammar:4640:ex:points:1":"〜ましょう: let's …","exam:4640:zh":"I left home ten minutes earlier than usual so I wouldn't be late.","exam:4640:why":"「十分早く」 means ten minutes early. 「遅く」 means later, which is the opposite of the goal of not being late."},"4641":{"example:4641:exzh":"At night, I heard a noise from inside."},"4642":{"example:4642:exzh":"It is important to clean up dog poop."},"4643":{"example:4643:exzh":"Please wait until the construction is finished."},"4644":{"example:4644:exzh":"It is important to use a shelter during a disaster.","example:4644:exzh2":"This shelter is safe and comfortable.","example:4644:exzh3":"A shelter is needed to protect the animals.","example:4644:exzh4":"Various activities are held inside the shelter.","example:4644:exzh5":"He lives in a shelter."},"4645":{"example:4645:exzh":"I work managing a company's finances.","example:4645:exzh2":"It is important to prepare financial reports.","example:4645:exzh3":"It is necessary to hire a financial expert.","example:4645:exzh4":"It is a job that requires financial knowledge.","example:4645:exzh5":"She is a finance teacher."},"4646":{"example:4646:exzh":"The children love watching magic tricks.","example:4646:exzh2":"He is good at performing magic tricks.","example:4646:exzh3":"The magic show was fun.","example:4646:exzh4":"I bought some magic props.","example:4646:exzh5":"Watching magic tricks is always exciting."},"4647":{"example:4647:exzh":"There is no falsehood in what he says.","example:4647:exzh2":"I want a friend who is not fake.","example:4647:exzh3":"It is hard to see through a lie.","example:4647:exzh4":"I don't want to live a fake life.","example:4647:exzh5":"She had a fake smile on her face."},"4648":{"example:4648:exzh":"Japan's lower house is called the House of Representatives.","example:4648:exzh2":"That law was passed in the lower house.","example:4648:exzh3":"The lower house election will be held next year.","example:4648:exzh4":"Members of the lower house have a lot of responsibility.","example:4648:exzh5":"The debate in the lower house has begun."},"4649":{"example:4649:exzh":"The thread got tangled.","example:4649:exzh2":"The tree branches are tangled together.","example:4649:exzh3":"He helped me untangle my hair.","example:4649:exzh4":"We need to solve a complicated problem.","example:4649:exzh5":"The bicycle chain is tangled."},"4650":{"example:4650:exzh":"I will go to the doctor to cure that illness.","example:4650:exzh2":"She worked hard to heal her injury.","example:4650:exzh3":"To recover quickly, rest is important.","example:4650:exzh4":"You can cure those symptoms by taking medicine.","example:4650:exzh5":"I go to the dentist every week to treat my cavity.","grammar:4650:ex:trans":"I go see a doctor to cure the illness.","grammar:4650:ex:structure":"病気を治すために、医者に行きます","grammar:4650:ex:explain":"The core points are the purpose marker 「〜ために」 and the transitive/intransitive pair. 「病気を治す」 means to cure an illness: 「治す」 is transitive (a person does the curing), and the object 「病気」 takes 「を」; adding 「ために」 gives in order to cure the illness. Note that 「治す（なおす）」 is transitive, while the intransitive 「治る」 means the illness gets better on its own; it also differs in meaning from the homophone 「直す」 (to fix or correct a thing or a mistake). In the second half, the 「に」 in 「医者に行きます」 marks the destination. The whole sentence means I go to the doctor in order to cure the illness.","grammar:4650:ex:words:0:zh":"that","grammar:4650:ex:words:0:pos":"pre-noun adjectival","grammar:4650:ex:words:1:zh":"illness","grammar:4650:ex:words:1:note":"びょうき","grammar:4650:ex:words:1:pos":"noun","grammar:4650:ex:words:2:zh":"(object marker)","grammar:4650:ex:words:2:pos":"particle","grammar:4650:ex:words:3:zh":"treatment","grammar:4650:ex:words:3:note":"なおす","grammar:4650:ex:words:3:pos":"verb","grammar:4650:ex:words:4:zh":"for the sake of","grammar:4650:ex:words:4:pos":"noun","grammar:4650:ex:words:5:zh":"(purpose)","grammar:4650:ex:words:5:pos":"particle","grammar:4650:ex:words:6:zh":"doctor","grammar:4650:ex:words:6:note":"いしゃ","grammar:4650:ex:words:6:pos":"noun","grammar:4650:ex:words:7:zh":"(destination)","grammar:4650:ex:words:7:pos":"particle","grammar:4650:ex:words:8:zh":"go","grammar:4650:ex:words:8:note":"いきます","grammar:4650:ex:words:8:pos":"verb","grammar:4650:ex:points:0":"❗治す（なおす）: to treat, to cure (transitive verb) ＋を; vs. 「治る（なおる）」 = (of an illness) to heal on its own, intransitive. Note the homophone 「直す」 = to fix, to correct (things, mistakes). 病気を治す = to cure an illness.","grammar:4650:ex:points:1":"治す: to treat (transitive; ≠直す, to fix) / 治る (intransitive).","grammar:4650:ex2:trans":"She worked hard to heal her own injury.","grammar:4650:ex2:structure":"けがを一生懸命治しました","grammar:4650:ex2:words:0:zh":"she","grammar:4650:ex2:words:0:note":"かのじょ","grammar:4650:ex2:words:0:pos":"pronoun","grammar:4650:ex2:words:1:zh":"(topic)","grammar:4650:ex2:words:1:pos":"particle","grammar:4650:ex2:words:2:zh":"oneself","grammar:4650:ex2:words:2:note":"じぶん","grammar:4650:ex2:words:2:pos":"pronoun","grammar:4650:ex2:words:3:zh":"'s","grammar:4650:ex2:words:3:pos":"particle","grammar:4650:ex2:words:4:zh":"scar","grammar:4650:ex2:words:4:note":"けが","grammar:4650:ex2:words:4:pos":"noun","grammar:4650:ex2:words:5:zh":"(object marker)","grammar:4650:ex2:words:5:pos":"particle","grammar:4650:ex2:words:6:zh":"full strength","grammar:4650:ex2:words:6:note":"いっしょうけんめい","grammar:4650:ex2:words:6:pos":"na-adjective","grammar:4650:ex2:words:7:zh":"treatment","grammar:4650:ex2:words:7:note":"なおしました","grammar:4650:ex2:words:7:pos":"verb","grammar:4650:ex2:points:0":"❗けがを治す: to treat an injury, to heal an injury.","grammar:4650:ex2:points:1":"けがを治す: to treat an injury.","grammar:4650:ex3:trans":"To heal quickly, rest is important.","grammar:4650:ex3:structure":"早く治すためには休むことが大切です","grammar:4650:ex3:words:0:zh":"fast","grammar:4650:ex3:words:0:note":"はやく","grammar:4650:ex3:words:0:pos":"adjective","grammar:4650:ex3:words:1:zh":"heal","grammar:4650:ex3:words:1:note":"なおす","grammar:4650:ex3:words:1:pos":"verb","grammar:4650:ex3:words:2:zh":"for the sake of","grammar:4650:ex3:words:2:pos":"noun","grammar:4650:ex3:words:3:zh":"(purpose)","grammar:4650:ex3:words:3:pos":"particle","grammar:4650:ex3:words:4:zh":"(contrast)","grammar:4650:ex3:words:4:pos":"particle","grammar:4650:ex3:words:5:zh":"rest","grammar:4650:ex3:words:5:note":"やすむ","grammar:4650:ex3:words:5:pos":"verb","grammar:4650:ex3:words:6:zh":"(nominalizer)","grammar:4650:ex3:words:6:pos":"noun","grammar:4650:ex3:words:7:zh":"(nominative)","grammar:4650:ex3:words:7:pos":"particle","grammar:4650:ex3:words:8:zh":"important","grammar:4650:ex3:words:8:note":"たいせつ","grammar:4650:ex3:words:8:pos":"na-adjective","grammar:4650:ex3:words:9:zh":"(polite form)","grammar:4650:ex3:words:9:pos":"copula","grammar:4650:ex3:points:0":"❗早く治す: to heal quickly, to recover as soon as possible.","grammar:4650:ex3:points:1":"早く治す: to recover quickly.","grammar:4650:ex4:trans":"Taking medicine can cure those symptoms.","grammar:4650:ex4:structure":"症状を治すことができます","grammar:4650:ex4:words:0:zh":"medicine","grammar:4650:ex4:words:0:note":"くすり","grammar:4650:ex4:words:0:pos":"noun","grammar:4650:ex4:words:1:zh":"(object marker)","grammar:4650:ex4:words:1:pos":"particle","grammar:4650:ex4:words:2:zh":"eat","grammar:4650:ex4:words:2:note":"のんで","grammar:4650:ex4:words:2:pos":"verb","grammar:4650:ex4:words:3:zh":"that","grammar:4650:ex4:words:3:pos":"pre-noun adjectival","grammar:4650:ex4:words:4:zh":"symptoms","grammar:4650:ex4:words:4:note":"しょうじょう","grammar:4650:ex4:words:4:pos":"noun","grammar:4650:ex4:words:5:zh":"(object marker)","grammar:4650:ex4:words:5:pos":"particle","grammar:4650:ex4:words:6:zh":"treatment","grammar:4650:ex4:words:6:note":"なおす","grammar:4650:ex4:words:6:pos":"verb","grammar:4650:ex4:words:7:zh":"(nominalizer)","grammar:4650:ex4:words:7:pos":"noun","grammar:4650:ex4:words:8:zh":"(nominative)","grammar:4650:ex4:words:8:pos":"particle","grammar:4650:ex4:words:9:zh":"be able to","grammar:4650:ex4:words:9:pos":"verb","grammar:4650:ex4:points:0":"❗症状を治す: to relieve / cure symptoms.","grammar:4650:ex4:points:1":"症状を治す: to cure symptoms.","grammar:4650:ex5:trans":"To get my cavity treated, I go to the dentist every week.","grammar:4650:ex5:structure":"〜を治すために、〜に通っています","grammar:4650:ex5:words:0:zh":"cavity","grammar:4650:ex5:words:0:note":"むしば","grammar:4650:ex5:words:0:pos":"noun","grammar:4650:ex5:words:1:zh":"(object)","grammar:4650:ex5:words:1:pos":"particle","grammar:4650:ex5:words:2:zh":"treatment","grammar:4650:ex5:words:2:note":"なおす","grammar:4650:ex5:words:2:pos":"verb","grammar:4650:ex5:words:3:zh":"for the sake of","grammar:4650:ex5:words:3:pos":"Expression","grammar:4650:ex5:words:4:zh":"every week","grammar:4650:ex5:words:4:note":"まいしゅう","grammar:4650:ex5:words:4:pos":"noun","grammar:4650:ex5:words:5:zh":"dentist","grammar:4650:ex5:words:5:note":"はいしゃ","grammar:4650:ex5:words:5:pos":"noun","grammar:4650:ex5:words:6:zh":"(destination)","grammar:4650:ex5:words:6:pos":"particle","grammar:4650:ex5:words:7:zh":"to go regularly","grammar:4650:ex5:words:7:note":"かよって; te-form","grammar:4650:ex5:words:7:pos":"verb","grammar:4650:ex5:words:8:zh":"(repeated ongoing action)","grammar:4650:ex5:words:8:pos":"auxiliary verb","grammar:4650:ex5:points:0":"「虫歯を治す」: 治す means to cure an illness or heal an injury, and its object takes 「を」; the intransitive 「治る」 means the illness heals on its own.","grammar:4650:ex5:points:1":"「dictionary form＋ために」 expresses purpose.","grammar:4650:ex5:points:2":"「通っています」 means going to a place regularly, over and over."},"4651":{"example:4651:exzh":"I want to go to an all-you-can-eat sushi restaurant.","example:4651:exzh2":"This restaurant has all-you-can-drink, so it is a good deal.","example:4651:exzh3":"He likes all-you-can-eat yakiniku.","example:4651:exzh4":"I enjoyed all-you-can-drink wine with friends.","example:4651:exzh5":"Lately, more and more restaurants offer all-you-can-eat curry."},"4652":{"example:4652:exzh":"Please cut that fruit into four pieces.","example:4652:exzh2":"Fish is usually cut into three fillets.","example:4652:exzh3":"With this knife, it is easy to cut by pressing down.","example:4652:exzh4":"Please cut the pizza into eight equal slices by pressing down with the knife.","example:4652:exzh5":"This meat is delicious if you slice it thin and grill it."},"4653":{"example:4653:exzh":"I went to the city office and got a certificate of residence.","example:4653:exzh2":"You can take care of all kinds of paperwork at the city office.","example:4653:exzh3":"The counter at the city office was crowded.","example:4653:exzh4":"When you move, you need to notify the city office.","example:4653:exzh5":"Paperwork at the city office is often difficult."},"4654":{"example:4654:exzh":"After watching the movie, we talked about our impressions.","example:4654:exzh2":"Please tell me what you thought of this book.","example:4654:exzh3":"His impressions were very interesting.","example:4654:exzh4":"I will try writing down my thoughts on the trip.","example:4654:exzh5":"I posted my recent thoughts on my blog."},"4655":{"example:4655:exzh":"He works at a company with a lifetime employment system.","example:4655:exzh2":"I need a friend for life.","example:4655:exzh3":"That contract is valid for life.","example:4655:exzh4":"I think lifelong learning is important.","example:4655:exzh5":"It is important to have a lifelong sense of responsibility."},"4656":{"example:4656:exzh":"This movie was the best!","example:4656:exzh2":"The weather today is great!","example:4656:exzh3":"Your cooking is the best!","example:4656:exzh4":"This is a great place, isn't it.","example:4656:exzh5":"I enjoyed a wonderful moment.","grammar:4656:ex:trans":"This movie was amazing!","grammar:4656:ex:structure":"〜は最高でした！","grammar:4656:ex:explain":"This sentence practices the polite past form of the na-adjective 「最高」. 「最高」 means \"the best, absolutely great\" — casual speech for rating something at the very top. 「最高でした」 is the past form of 「最高です」; since it's about a movie you've already seen, the past is used. The topic 「この映画は」 takes 「は」. The exclamation mark at the end carries strong emotion. The whole sentence is \"This movie was awesome!\" The point being practiced: when a na-adjective is the predicate, the polite past form is simply 「でした」, unlike i-adjectives, which change to 「かった」.","grammar:4656:ex:words:0:zh":"this","grammar:4656:ex:words:0:pos":"pre-noun adjectival","grammar:4656:ex:words:1:zh":"movie","grammar:4656:ex:words:1:note":"えいが","grammar:4656:ex:words:1:pos":"noun","grammar:4656:ex:words:2:zh":"(topic)","grammar:4656:ex:words:2:pos":"particle","grammar:4656:ex:words:3:zh":"the best","grammar:4656:ex:words:3:note":"さいこう","grammar:4656:ex:words:3:pos":"na-adjective","grammar:4656:ex:words:4:zh":"(past) was","grammar:4656:ex:words:4:pos":"copula","grammar:4656:ex:points:0":"❗「最高（さいこう）」: the best, absolutely great.","grammar:4656:ex:points:1":"「最高でした」: (past) it was amazing.","grammar:4656:ex2:trans":"The weather today is perfect!","grammar:4656:ex2:structure":"〜は最高です！","grammar:4656:ex2:words:0:zh":"today","grammar:4656:ex2:words:0:note":"きょう","grammar:4656:ex2:words:0:pos":"noun","grammar:4656:ex2:words:1:zh":"'s","grammar:4656:ex2:words:1:pos":"particle","grammar:4656:ex2:words:2:zh":"weather","grammar:4656:ex2:words:2:note":"てんき","grammar:4656:ex2:words:2:pos":"noun","grammar:4656:ex2:words:3:zh":"(topic)","grammar:4656:ex2:words:3:pos":"particle","grammar:4656:ex2:words:4:zh":"the best","grammar:4656:ex2:words:4:note":"さいこう","grammar:4656:ex2:words:4:pos":"na-adjective","grammar:4656:ex2:words:5:zh":"(polite form)","grammar:4656:ex2:words:5:pos":"copula","grammar:4656:ex2:points:0":"「天気は最高」: the weather is the best.","grammar:4656:ex2:points:1":"「最高」: superb.","grammar:4656:ex3:trans":"Your cooking is amazing!","grammar:4656:ex3:structure":"〜、最高です！","grammar:4656:ex3:words:0:zh":"you","grammar:4656:ex3:words:0:pos":"pronoun","grammar:4656:ex3:words:1:zh":"'s","grammar:4656:ex3:words:1:pos":"particle","grammar:4656:ex3:words:2:zh":"dish / cuisine","grammar:4656:ex3:words:2:note":"りょうり","grammar:4656:ex3:words:2:pos":"noun","grammar:4656:ex3:words:3:zh":"the best","grammar:4656:ex3:words:3:note":"さいこう","grammar:4656:ex3:words:3:pos":"na-adjective","grammar:4656:ex3:words:4:zh":"(polite form)","grammar:4656:ex3:words:4:pos":"copula","grammar:4656:ex3:points:0":"「あなたの料理」: your cooking.","grammar:4656:ex3:points:1":"「最高です」: it's amazing.","grammar:4656:ex4:trans":"This really is a great place.","grammar:4656:ex4:structure":"〜は最高の〜ですね","grammar:4656:ex4:words:0:zh":"here","grammar:4656:ex4:words:0:pos":"pronoun","grammar:4656:ex4:words:1:zh":"(topic)","grammar:4656:ex4:words:1:pos":"particle","grammar:4656:ex4:words:2:zh":"the best","grammar:4656:ex4:words:2:note":"さいこう","grammar:4656:ex4:words:2:pos":"noun","grammar:4656:ex4:words:3:zh":"'s","grammar:4656:ex4:words:3:pos":"particle","grammar:4656:ex4:words:4:zh":"place","grammar:4656:ex4:words:4:note":"ばしょ","grammar:4656:ex4:words:4:pos":"noun","grammar:4656:ex4:words:5:zh":"is","grammar:4656:ex4:words:5:pos":"copula","grammar:4656:ex4:words:6:zh":"right?","grammar:4656:ex4:words:6:pos":"particle","grammar:4656:ex4:points:0":"❗「最高の＋noun」: the best ….","grammar:4656:ex4:points:1":"「最高の場所」: the best place.","grammar:4656:ex5:trans":"I enjoyed a wonderful moment.","grammar:4656:ex5:structure":"最高な〜を楽しみました","grammar:4656:ex5:words:0:zh":"the best","grammar:4656:ex5:words:0:note":"さいこう","grammar:4656:ex5:words:0:pos":"na-adjective","grammar:4656:ex5:words:1:zh":"(attributive form)","grammar:4656:ex5:words:1:pos":"auxiliary verb","grammar:4656:ex5:words:2:zh":"moment","grammar:4656:ex5:words:2:note":"しゅんかん","grammar:4656:ex5:words:2:pos":"noun","grammar:4656:ex5:words:3:zh":"(object marker)","grammar:4656:ex5:words:3:pos":"particle","grammar:4656:ex5:words:4:zh":"enjoyed","grammar:4656:ex5:words:4:note":"たのしみました","grammar:4656:ex5:words:4:pos":"verb","grammar:4656:ex5:points:0":"「最高な瞬間」: the best moment.","grammar:4656:ex5:points:1":"「瞬間を楽しむ」: to enjoy the moment."},"4657":{"example:4657:exzh":"The tree branch broke.","example:4657:exzh2":"He is playing with a branch.","example:4657:exzh3":"A little bird is perched on the branch.","example:4657:exzh4":"This branch is sturdy.","example:4657:exzh5":"In autumn the branches change color."},"4658":{"example:4658:exzh":"Marguerites are blooming in the garden.","example:4658:exzh2":"Marguerite flowers are white.","example:4658:exzh3":"She likes marguerites.","example:4658:exzh4":"Let's go see the marguerites.","example:4658:exzh5":"Marguerites are spring flowers."},"4659":{"example:4659:exzh":"Would it be all right if I visited your home?","example:4659:exzh2":"Where do you live?","example:4659:exzh3":"Is your family doing well?","example:4659:exzh4":"Your home is lovely.","example:4659:exzh5":"Let's have tea at your home."},"4660":{"example:4660:exzh":"He is a powerful leader.","example:4660:exzh2":"Sing with a powerful voice.","example:4660:exzh3":"We need strong support.","example:4660:exzh4":"He has a strong will.","example:4660:exzh5":"She is a strong person."},"4661":{"example:4661:exzh":"New employees receive training.","example:4661:exzh2":"The training starts next week.","example:4661:exzh3":"Once the training is over, I will submit the report.","example:4661:exzh4":"I took part in various training programs.","example:4661:exzh5":"The training content was very helpful."},"4662":{"example:4662:exzh":"He overwhelmed his competitor.","example:4662:exzh2":"That performance was overwhelming.","example:4662:exzh3":"I was overwhelmed with a sense of respect.","example:4662:exzh4":"It overwhelmingly surpassed the figures.","example:4662:exzh5":"Overwhelming someone is not easy."},"4664":{"example:4664:exzh":"In addition, this meeting is important.","example:4664:exzh2":"Also, please keep an eye on tomorrow's weather.","example:4664:exzh3":"Also, questions will be taken later.","example:4664:exzh4":"This is the final report.","example:4664:exzh5":"Also, there are no changes."},"4665":{"example:4665:exzh":"I enter the venue.","example:4665:exzh2":"Please knock before entering the room.","example:4665:exzh3":"He entered the school.","example:4665:exzh4":"You need to be careful when entering.","example:4665:exzh5":"Vehicles are not allowed beyond this point."},"4666":{"example:4666:exzh":"Children love mischief.","example:4666:exzh2":"Playing pranks is fun.","example:4666:exzh3":"He played a prank on his friend.","example:4666:exzh4":"If your mischief goes too far, you get scolded.","example:4666:exzh5":"The mischievous kids got together and played."},"4667":{"example:4667:exzh":"We met face-to-face at a coffee shop.","example:4667:exzh2":"It's been a long time since I met him in person.","example:4667:exzh3":"I like talking in person.","example:4667:exzh4":"We'll hold an in-person meeting.","example:4667:exzh5":"I usually see him in person."},"4668":{"example:4668:exzh":"His solution was very clever.","example:4668:exzh2":"This device is cleverly designed.","example:4668:exzh3":"Her phrasing was clever.","example:4668:exzh4":"A clever tactic brought victory.","example:4668:exzh5":"Isn't there a clever way to solve this problem?"},"4669":{"example:4669:exzh":"He lives a luxurious life.","example:4669:exzh2":"This hotel offers luxurious service.","example:4669:exzh3":"You should enjoy a luxurious meal once in a while.","example:4669:exzh4":"She was criticized for living extravagantly.","example:4669:exzh5":"Don't spend too much money on extravagant shopping."},"4671":{"example:4671:exzh":"I worked hard and put it into action right away.","example:4671:exzh2":"We have to solve this problem right away.","example:4671:exzh3":"The new project started right away.","example:4671:exzh4":"I'll send it by email right away.","example:4671:exzh5":"Let's hold the meeting right away."},"4672":{"example:4672:exzh":"He's an acquaintance of mine.","example:4672:exzh2":"I received an invitation from an acquaintance.","example:4672:exzh3":"I'm planning to meet an acquaintance.","example:4672:exzh4":"She introduced an acquaintance to me.","example:4672:exzh5":"I'm going to an acquaintance's wedding."},"4673":{"example:4673:exzh":"Technology evolves quickly.","example:4673:exzh2":"It's important to learn new technology.","example:4673:exzh3":"Technology has changed our lives.","example:4673:exzh4":"Advances in technology have brought us a convenient era.","example:4673:exzh5":"He knows a lot about technology."},"4674":{"example:4674:exzh":"Let's cherish the blessings of nature.","example:4674:exzh2":"She received a blessing.","example:4674:exzh3":"Rain is a blessing of the earth.","example:4674:exzh4":"It's important to be grateful for blessings.","example:4674:exzh5":"It is a being that brings blessings."},"4675":{"example:4675:exzh":"I understood his intent.","example:4675:exzh2":"It's important to convey your intent.","example:4675:exzh3":"I acted as she wished.","example:4675:exzh4":"This meaning is exactly what I want to say.","example:4675:exzh5":"I wrote a letter to show my intent."},"4676":{"example:4676:exzh":"I'm taking part in that association.","example:4676:exzh2":"I want to contribute to the association's activities.","example:4676:exzh3":"The association carries out activities that benefit the community.","example:4676:exzh4":"You need to complete procedures to become a member of the association.","example:4676:exzh5":"He is the chairman of that association."},"4677":{"example:4677:exzh":"He is always caring toward me.","example:4677:exzh2":"Parents should be caring toward their children.","example:4677:exzh3":"Words of care are needed.","example:4677:exzh4":"The grandfather is caring for his grandchild.","example:4677:exzh5":"It's important to be considerate of your friends' feelings."},"4678":{"example:4678:exzh":"I was overwhelmed by his momentum.","example:4678:exzh2":"You should act while you have momentum.","example:4678:exzh3":"The economy is gaining momentum.","example:4678:exzh4":"The party is still going strong.","example:4678:exzh5":"I want to keep up this momentum."},"4679":{"example:4679:exzh":"This chain is very sturdy.","example:4679:exzh2":"The shop is a chain store.","example:4679:exzh3":"I fixed the bicycle using a chain.","example:4679:exzh4":"He bought a chain.","example:4679:exzh5":"The price of the chain is high."},"4680":{"example:4680:exzh":"The parade was a lot of fun.","example:4680:exzh2":"There's a parade in this town every year.","example:4680:exzh3":"I'm going to see the parade.","example:4680:exzh4":"Everyone is looking forward to the parade.","example:4680:exzh5":"What time exactly is the parade?"},"4681":{"example:4681:exzh":"I get up at six every morning.","example:4681:exzh2":"He always gets up late.","example:4681:exzh3":"Let's decide what time to get up.","example:4681:exzh4":"I'm getting up at five tomorrow, so I'll go to bed early.","example:4681:exzh5":"I got up early today.","grammar:4681:ex:trans":"I get up at six every morning.","grammar:4681:ex:structure":"〜時に起きます","grammar:4681:ex:explain":"The key point is the intransitive verb 「起きる」, meaning \"to get up, to wake up\" (it can also refer to an event happening). The subject gets up on its own, with no object. In 「6時に起きます」, 「に」 marks a specific point in time (what time). 「毎朝」 is the time adverb \"every morning\"; nouns of frequency or time period like this can work as adverbials without a particle. 「起きます」 is the polite present form, expressing a habit. The whole sentence is \"I get up at six every morning.\" The points practiced are 「に」 marking a point in time and the intransitive nature of 「起きる」.","grammar:4681:ex:words:0:zh":"every morning","grammar:4681:ex:words:0:note":"まいあさ","grammar:4681:ex:words:0:pos":"adverb","grammar:4681:ex:words:1:zh":"Six o’clock","grammar:4681:ex:words:1:note":"ろくじ","grammar:4681:ex:words:1:pos":"noun","grammar:4681:ex:words:2:zh":"(point in time)","grammar:4681:ex:words:2:pos":"particle","grammar:4681:ex:words:3:zh":"to get up","grammar:4681:ex:words:3:note":"おきます","grammar:4681:ex:words:3:pos":"verb","grammar:4681:ex:points:0":"❗「起きる（おきる）」: to get up, to wake up (intransitive verb).","grammar:4681:ex:points:1":"「6時に起きる」: to get up at six.","grammar:4681:ex2:trans":"He always gets up late.","grammar:4681:ex2:structure":"いつも遅く起きます","grammar:4681:ex2:words:0:zh":"he","grammar:4681:ex2:words:0:note":"かれ","grammar:4681:ex2:words:0:pos":"pronoun","grammar:4681:ex2:words:1:zh":"(topic)","grammar:4681:ex2:words:1:pos":"particle","grammar:4681:ex2:words:2:zh":"always","grammar:4681:ex2:words:2:pos":"adverb","grammar:4681:ex2:words:3:zh":"late (adverb)","grammar:4681:ex2:words:3:note":"おそく","grammar:4681:ex2:words:3:pos":"adverb","grammar:4681:ex2:words:4:zh":"to get up","grammar:4681:ex2:words:4:note":"おきます","grammar:4681:ex2:words:4:pos":"verb","grammar:4681:ex2:points:0":"「遅く起きる」: to get up late.","grammar:4681:ex2:points:1":"いつも: always.","grammar:4681:ex3:trans":"Let's decide what time to get up.","grammar:4681:ex3:structure":"〜を決めましょう","grammar:4681:ex3:words:0:zh":"to get up","grammar:4681:ex3:words:0:note":"おきる","grammar:4681:ex3:words:0:pos":"verb","grammar:4681:ex3:words:1:zh":"time","grammar:4681:ex3:words:1:note":"じかん","grammar:4681:ex3:words:1:pos":"noun","grammar:4681:ex3:words:2:zh":"(object marker)","grammar:4681:ex3:words:2:pos":"particle","grammar:4681:ex3:words:3:zh":"let's decide","grammar:4681:ex3:words:3:note":"きめましょう","grammar:4681:ex3:words:3:pos":"verb","grammar:4681:ex3:points:0":"「起きる時間」: the time to get up (attributive form).","grammar:4681:ex3:points:1":"〜ましょう: a suggestion.","grammar:4681:ex4:trans":"I have to get up at five tomorrow, so I'll go to bed early.","grammar:4681:ex4:structure":"〜に起きるので、〜ます","grammar:4681:ex4:words:0:zh":"tomorrow","grammar:4681:ex4:words:0:note":"あした","grammar:4681:ex4:words:0:pos":"noun","grammar:4681:ex4:words:1:zh":"(topic)","grammar:4681:ex4:words:1:pos":"particle","grammar:4681:ex4:words:2:zh":"five o'clock","grammar:4681:ex4:words:2:note":"ごじ","grammar:4681:ex4:words:2:pos":"noun","grammar:4681:ex4:words:3:zh":"(time)","grammar:4681:ex4:words:3:pos":"particle","grammar:4681:ex4:words:4:zh":"to get up","grammar:4681:ex4:words:4:note":"おきる","grammar:4681:ex4:words:4:pos":"verb","grammar:4681:ex4:words:5:zh":"because","grammar:4681:ex4:words:5:pos":"particle","grammar:4681:ex4:words:6:zh":"early","grammar:4681:ex4:words:6:note":"はやく; the adverb form of 早い","grammar:4681:ex4:words:6:pos":"adjective","grammar:4681:ex4:words:7:zh":"sleep","grammar:4681:ex4:words:7:note":"ねます","grammar:4681:ex4:words:7:pos":"verb","grammar:4681:ex4:points:0":"「五時に起きる」: 「起きる」 means to get up, and a specific time takes に.","grammar:4681:ex4:points:1":"「〜ので」: shows a cause — \"because …, ….\"","grammar:4681:ex4:points:2":"「早く寝ます」: 「早い」 becomes 「早く」 to modify a verb.","grammar:4681:ex5:trans":"I got up relatively early today.","grammar:4681:ex5:structure":"早く起きました","grammar:4681:ex5:words:0:zh":"today","grammar:4681:ex5:words:0:note":"きょう","grammar:4681:ex5:words:0:pos":"noun","grammar:4681:ex5:words:1:zh":"(topic)","grammar:4681:ex5:words:1:pos":"particle","grammar:4681:ex5:words:2:zh":"early (as an adverb)","grammar:4681:ex5:words:2:note":"はやく","grammar:4681:ex5:words:2:pos":"adverb","grammar:4681:ex5:words:3:zh":"got up","grammar:4681:ex5:words:3:note":"おきました","grammar:4681:ex5:words:3:pos":"verb","grammar:4681:ex5:points:0":"早く起きる: to get up early.","grammar:4681:ex5:points:1":"起きる→起きました。","exam:4681:zh":"Even when I wake up in the morning, I don't want to get out of bed, so I lie there for a while.","exam:4681:why":"「ベッドから起きる」 means getting up out of bed. 「寝る」 means sleeping or lying down, the opposite direction from getting up out of bed."},"4682":{"example:4682:exzh":"That thug is scary.","example:4682:exzh2":"Watch out for thugs.","example:4682:exzh3":"There are more and more thugs in town.","example:4682:exzh4":"Thugs are the cause of trouble.","example:4682:exzh5":"He behaves like a thug."},"4683":{"example:4683:exzh":"One evening, I went out with a friend.","example:4683:exzh2":"That evening is a special memory.","example:4683:exzh3":"I can't forget what happened that evening.","example:4683:exzh4":"One evening, I talked with him.","example:4683:exzh5":"She only contacted me for one evening."},"4684":{"example:4684:exzh":"He's a first-rate soccer player.","example:4684:exzh2":"This shop offers first-class service.","example:4684:exzh3":"I'm happy I got into a top-tier university.","example:4684:exzh4":"I want to eat first-class food.","example:4684:exzh5":"He is called a first-rate businessman."},"4685":{"example:4685:exzh":"Please mix the eggs and milk.","example:4685:exzh2":"Mix dressing into the salad.","example:4685:exzh3":"Mix paints to make a new color.","example:4685:exzh4":"Mix the rice with water.","example:4685:exzh5":"Mixing the ingredients makes it taste better.","grammar:4685:ex:trans":"Please mix the eggs and milk together.","grammar:4685:ex:structure":"〜と〜を混ぜてください","grammar:4685:ex:explain":"The key word is the transitive verb 「混ぜる」, meaning to mix or stir — a person does the mixing, which makes it transitive; its intransitive counterpart is 「混ざる」 (to get mixed together on its own). The things you mix are joined with 「と」 and then marked with 「を」: 「卵と牛乳を混ぜる」 means to mix the eggs and milk together, with 「と」 listing the items involved. 「〜てください」 makes it a request. The whole sentence is: Please mix the eggs and milk together. The drill points are the transitive/intransitive pair (混ぜる／混ざる) and the joined object 「AとBを」.","grammar:4685:ex:words:0:zh":"egg","grammar:4685:ex:words:0:note":"たまご","grammar:4685:ex:words:0:pos":"noun","grammar:4685:ex:words:1:zh":"with","grammar:4685:ex:words:1:pos":"particle","grammar:4685:ex:words:2:zh":"milk","grammar:4685:ex:words:2:note":"ぎゅうにゅう","grammar:4685:ex:words:2:pos":"noun","grammar:4685:ex:words:3:zh":"(object marker)","grammar:4685:ex:words:3:pos":"particle","grammar:4685:ex:words:4:zh":"to mix","grammar:4685:ex:words:4:note":"まぜて","grammar:4685:ex:words:4:pos":"verb","grammar:4685:ex:words:5:zh":"please","grammar:4685:ex:words:5:pos":"auxiliary verb","grammar:4685:ex:points:0":"❗混ぜる (まぜる): to mix, to stir (transitive verb); vs 混ざる (intransitive, to get mixed in); AとBを混ぜる = mix A and B","grammar:4685:ex:points:1":"卵と牛乳を混ぜる: to mix eggs and milk.","grammar:4685:ex2:trans":"Mix the dressing into the salad.","grammar:4685:ex2:structure":"〜に〜を混ぜる","grammar:4685:ex2:words:0:zh":"salad","grammar:4685:ex2:words:0:note":"loanword","grammar:4685:ex2:words:0:pos":"noun","grammar:4685:ex2:words:1:zh":"(the destination point)","grammar:4685:ex2:words:1:pos":"particle","grammar:4685:ex2:words:2:zh":"dressing","grammar:4685:ex2:words:2:note":"loanword","grammar:4685:ex2:words:2:pos":"noun","grammar:4685:ex2:words:3:zh":"(object marker)","grammar:4685:ex2:words:3:pos":"particle","grammar:4685:ex2:words:4:zh":"to mix","grammar:4685:ex2:words:4:note":"まぜる","grammar:4685:ex2:words:4:pos":"verb","grammar:4685:ex2:points:0":"❗〜に〜を混ぜる: to mix … into …; ドレッシング = salad dressing","grammar:4685:ex2:points:1":"ドレッシングを混ぜる: to mix in the dressing.","grammar:4685:ex3:trans":"Mix paints to make a new color.","grammar:4685:ex3:structure":"〜を混ぜて〜を作る","grammar:4685:ex3:words:0:zh":"paint","grammar:4685:ex3:words:0:note":"loanword","grammar:4685:ex3:words:0:pos":"noun","grammar:4685:ex3:words:1:zh":"(object marker)","grammar:4685:ex3:words:1:pos":"particle","grammar:4685:ex3:words:2:zh":"to mix","grammar:4685:ex3:words:2:note":"まぜて","grammar:4685:ex3:words:2:pos":"verb","grammar:4685:ex3:words:3:zh":"new","grammar:4685:ex3:words:3:note":"あたらしい","grammar:4685:ex3:words:3:pos":"adjective","grammar:4685:ex3:words:4:zh":"color","grammar:4685:ex3:words:4:note":"いろ","grammar:4685:ex3:words:4:pos":"noun","grammar:4685:ex3:words:5:zh":"(object marker)","grammar:4685:ex3:words:5:pos":"particle","grammar:4685:ex3:words:6:zh":"making","grammar:4685:ex3:words:6:note":"つくる","grammar:4685:ex3:words:6:pos":"verb","grammar:4685:ex3:points:0":"❗ペンキを混ぜる: to mix paint; ペンキ = paint","grammar:4685:ex3:points:1":"ペンキを混ぜる: to mix paint.","grammar:4685:ex4:trans":"Mix the rice with water.","grammar:4685:ex4:structure":"〜を〜と混ぜる","grammar:4685:ex4:words:0:zh":"rice","grammar:4685:ex4:words:0:note":"こめ","grammar:4685:ex4:words:0:pos":"noun","grammar:4685:ex4:words:1:zh":"(object marker)","grammar:4685:ex4:words:1:pos":"particle","grammar:4685:ex4:words:2:zh":"water","grammar:4685:ex4:words:2:note":"みず","grammar:4685:ex4:words:2:pos":"noun","grammar:4685:ex4:words:3:zh":"with","grammar:4685:ex4:words:3:pos":"particle","grammar:4685:ex4:words:4:zh":"to mix","grammar:4685:ex4:words:4:note":"まぜる","grammar:4685:ex4:words:4:pos":"verb","grammar:4685:ex4:points:0":"❗〜を〜と混ぜる: to mix … with …; 米 = uncooked rice","grammar:4685:ex4:points:1":"米と水を混ぜる: to mix rice and water.","grammar:4685:ex5:trans":"Mix the ingredients and it turns out tastier.","grammar:4685:ex5:structure":"〜を混ぜると〜くなる","grammar:4685:ex5:words:0:zh":"ingredient","grammar:4685:ex5:words:0:note":"ざいりょう","grammar:4685:ex5:words:0:pos":"noun","grammar:4685:ex5:words:1:zh":"(object marker)","grammar:4685:ex5:words:1:pos":"particle","grammar:4685:ex5:words:2:zh":"to mix","grammar:4685:ex5:words:2:note":"まぜる","grammar:4685:ex5:words:2:pos":"verb","grammar:4685:ex5:words:3:zh":"(as soon as…)","grammar:4685:ex5:words:3:pos":"particle","grammar:4685:ex5:words:4:zh":"to become tastier","grammar:4685:ex5:words:4:note":"おいしく","grammar:4685:ex5:words:4:pos":"adjective","grammar:4685:ex5:words:5:zh":"become","grammar:4685:ex5:words:5:pos":"verb","grammar:4685:ex5:points:0":"❗〜と: if … then …; 美味しくなる = to become tastier (美味しい → 美味しくなる).","grammar:4685:ex5:points:1":"混ぜると美味しくなる: mixing it makes it tastier."},"4686":{"example:4686:exzh":"This food contains a lot of nutrients.","example:4686:exzh2":"I try to eat meals with nutrition in mind.","example:4686:exzh3":"A lack of nutrients is bad for your body.","example:4686:exzh4":"Children need plenty of nutrition.","example:4686:exzh5":"You can also use nutritional supplements."},"4688":{"example:4688:exzh":"Hunting is permitted in this area.","example:4688:exzh2":"What are the requirements for getting a hunting license?","example:4688:exzh3":"Hunting is part of traditional food culture.","example:4688:exzh4":"He went to the mountains to hunt.","example:4688:exzh5":"Hunting also affects nature conservation."},"4689":{"example:4689:exzh":"This condition should be excluded.","example:4689:exzh2":"I listed the people who are excluded.","example:4689:exzh3":"Special cases may be excluded.","example:4689:exzh4":"You could say exclusion is unfair.","example:4689:exzh5":"Exclusions from the rules depend on discretion."},"4690":{"example:4690:exzh":"A checkpoint is in progress.","example:4690:exzh2":"The police are conducting a checkpoint.","example:4690:exzh3":"There's a checkpoint on this road.","example:4690:exzh4":"You can't pass through during a checkpoint.","example:4690:exzh5":"I passed through the checkpoint."},"4691":{"example:4691:exzh":"We are compatriots.","example:4691:exzh2":"It's important to have a sense of kinship with your compatriots.","example:4691:exzh3":"He is my compatriot.","example:4691:exzh4":"Compatriots help each other.","example:4691:exzh5":"We need to be considerate toward our compatriots."},"4692":{"example:4692:exzh":"The police are conducting an interrogation.","example:4692:exzh2":"We need to conduct an interrogation.","example:4692:exzh3":"The interrogation is rigorous.","example:4692:exzh4":"He was interrogated.","example:4692:exzh5":"The results of the interrogation are out."},"4693":{"example:4693:exzh":"That's not very good.","example:4693:exzh2":"I'm not very hungry.","example:4693:exzh3":"I don't really like this outfit.","example:4693:exzh4":"He's someone who doesn't talk much.","example:4693:exzh5":"It's simply too easy.","grammar:4693:ex:trans":"That is not very good.","grammar:4693:ex:structure":"それ＋は＋あまり＋negative い-adjective。「あまり〜ない」＝not very ….","grammar:4693:ex:explain":"The key point is the adverbial pattern 「あまり〜ない」, meaning “not very” or “not much.” 「あまり」 must be followed by a negative form. 「あまり良くない」 means “not very good,” and 「良くない」 is the negative form of 「良い（いい）」 (note that the negative uses 「良く」, rather than 「いく」). 「それは」 marks the topic with 「は」. The whole sentence means “That is not very good.” The practice points are using 「あまり」 with a negative form and remembering the special negative form 「良くない」 of 「いい／良い」.","grammar:4693:ex:words:0:zh":"that","grammar:4693:ex:words:0:pos":"pronoun","grammar:4693:ex:words:1:zh":"(topic marker)","grammar:4693:ex:words:1:pos":"particle","grammar:4693:ex:words:2:zh":"(not) much","grammar:4693:ex:words:2:note":"pairs with a negative predicate","grammar:4693:ex:words:2:pos":"adverb","grammar:4693:ex:words:3:zh":"bad / not good","grammar:4693:ex:words:3:note":"よくない","grammar:4693:ex:words:3:pos":"adjective","grammar:4693:ex:words:4:zh":"(polite form)","grammar:4693:ex:words:4:pos":"copula","grammar:4693:ex:points:0":"あまり〜ない：not very … (あまり良くない＝not very good)","grammar:4693:ex:points:1":"良くない: not good (the negative of 良い)","grammar:4693:ex2:trans":"I'm not very hungry.","grammar:4693:ex2:structure":"あまり＋お腹が＋空いていません。「あまり〜ない」＝not very …。「お腹が空く」＝be hungry.","grammar:4693:ex2:words:0:zh":"(not) much","grammar:4693:ex2:words:0:pos":"adverb","grammar:4693:ex2:words:1:zh":"stomach","grammar:4693:ex2:words:1:note":"おなか","grammar:4693:ex2:words:1:pos":"noun","grammar:4693:ex2:words:2:zh":"(nominative)","grammar:4693:ex2:words:2:pos":"particle","grammar:4693:ex2:words:3:zh":"not hungry","grammar:4693:ex2:words:3:note":"すいていません；negative of 〜ている","grammar:4693:ex2:words:3:pos":"verb","grammar:4693:ex2:points:0":"あまり〜ない：not very …","grammar:4693:ex2:points:1":"お腹が空く：be hungry (negative here＝not hungry)","grammar:4693:ex3:trans":"I do not like these clothes very much.","grammar:4693:ex3:structure":"この＋noun＋は＋あまり＋好きではありません。「あまり〜ない」＝not very ….","grammar:4693:ex3:words:0:zh":"this","grammar:4693:ex3:words:0:pos":"pre-noun adjectival","grammar:4693:ex3:words:1:zh":"clothes","grammar:4693:ex3:words:1:note":"ふく","grammar:4693:ex3:words:1:pos":"noun","grammar:4693:ex3:words:2:zh":"(topic marker)","grammar:4693:ex3:words:2:pos":"particle","grammar:4693:ex3:words:3:zh":"(not) much","grammar:4693:ex3:words:3:pos":"adverb","grammar:4693:ex3:words:4:zh":"don't like","grammar:4693:ex3:words:4:note":"すきではありません；negative","grammar:4693:ex3:words:4:pos":"na-adjective","grammar:4693:ex3:points:0":"あまり〜ない：not very …","grammar:4693:ex3:points:1":"好きではありません：do not like (negative な-adjective in the polite form)","grammar:4693:ex4:trans":"He is someone who does not talk much.","grammar:4693:ex4:structure":"〜は＋〔あまり話さない〕＋人＋です。「あまり話さない」 modifies 「人」.","grammar:4693:ex4:words:0:zh":"he","grammar:4693:ex4:words:0:note":"かれ","grammar:4693:ex4:words:0:pos":"pronoun","grammar:4693:ex4:words:1:zh":"(topic marker)","grammar:4693:ex4:words:1:pos":"particle","grammar:4693:ex4:words:2:zh":"(not) much","grammar:4693:ex4:words:2:pos":"adverb","grammar:4693:ex4:words:3:zh":"not talk","grammar:4693:ex4:words:3:note":"はなさない；nai-form modifying a noun","grammar:4693:ex4:words:3:pos":"verb","grammar:4693:ex4:words:4:zh":"person","grammar:4693:ex4:words:4:note":"ひと","grammar:4693:ex4:words:4:pos":"noun","grammar:4693:ex4:words:5:zh":"is","grammar:4693:ex4:words:5:pos":"copula","grammar:4693:ex4:points:0":"あまり〜ない：not very …","grammar:4693:ex4:points:1":"Verb nai-form modifying a noun: 話さない人 (a person who does not talk much)","grammar:4693:ex5:trans":"It is too easy.","grammar:4693:ex5:structure":"あまりにも＋な-adjective＋です。「あまりにも」＝too … (used with an affirmative form to emphasize excess).","grammar:4693:ex5:words:0:zh":"too; excessively","grammar:4693:ex5:words:0:note":"あまりに＋も for emphasis","grammar:4693:ex5:words:0:pos":"adverb","grammar:4693:ex5:words:1:zh":"easy","grammar:4693:ex5:words:1:note":"かんたん","grammar:4693:ex5:words:1:pos":"na-adjective","grammar:4693:ex5:words:2:zh":"(polite form)","grammar:4693:ex5:words:2:pos":"copula","grammar:4693:ex5:points:0":"あまりにも：too … (emphasizes excess; followed by an affirmative form)","grammar:4693:ex5:points:1":"※Compare あまり〜ない (not very …)"},"4694":{"example:4694:exzh":"The heartbeat has gotten faster.","example:4694:exzh2":"Let's measure the heartbeat.","example:4694:exzh3":"The heart rate is normal.","example:4694:exzh4":"The heart rate goes up after exercise.","example:4694:exzh5":"Can you feel the heartbeat?"},"4695":{"example:4695:exzh":"Mutual understanding is necessary.","example:4695:exzh2":"They help each other.","example:4695:exzh3":"Mutual trust is important.","example:4695:exzh4":"Building a mutual relationship is important.","example:4695:exzh5":"Mutual respect is necessary."},"4696":{"example:4696:exzh":"This book is thick.","example:4696:exzh2":"I'll make a soup with thick slices of meat in it.","example:4696:exzh3":"His fingers are thick.","example:4696:exzh4":"A thick coat is necessary.","example:4696:exzh5":"This wall is thick.","grammar:4696:ex:trans":"This book is very thick.","grammar:4696:ex:structure":"この＋noun＋は＋i-adjective＋です。","grammar:4696:ex:explain":"This is a descriptive sentence using 「AはBです」. 「この本は」 marks the topic with 「は」, and 「厚い」 is the い-adjective meaning “thick”; adding 「です」 makes it polite. Note that 「厚い（あつい）」, 「暑い」 (hot weather), and 「熱い」 (hot to the touch) have the same pronunciation but different kanji and meanings. Use the kanji and context to tell them apart. The whole sentence means “This book is very thick.” The practice points are the three homophones pronounced 「あつい」 and the polite predicate formed by adding 「です」 directly to an い-adjective.","grammar:4696:ex:words:0:zh":"this","grammar:4696:ex:words:0:pos":"pre-noun adjectival","grammar:4696:ex:words:1:zh":"book","grammar:4696:ex:words:1:note":"ほん","grammar:4696:ex:words:1:pos":"noun","grammar:4696:ex:words:2:zh":"(topic marker)","grammar:4696:ex:words:2:pos":"particle","grammar:4696:ex:words:3:zh":"Thick","grammar:4696:ex:words:3:note":"あつい","grammar:4696:ex:words:3:pos":"adjective","grammar:4696:ex:words:4:zh":"(polite form)","grammar:4696:ex:words:4:pos":"copula","grammar:4696:ex:points:0":"厚い：thick (あつい; note that it sounds the same as 暑い/熱い)","grammar:4696:ex:points:1":"この本：this book","grammar:4696:ex2:trans":"I will make soup with thick slices of meat.","grammar:4696:ex2:structure":"［〜を入れた］スープを作ります","grammar:4696:ex2:explain":"「厚い」 directly modifies 「肉」, and the first 「を」 marks the ingredient being added. The entire phrase 「厚い肉を入れたスープ」 refers to the soup to be made, and the second 「を」 marks the object of 「作る」. Even when the sentence ending refers to soup that will be made, 「入れた」 can describe the ingredients included in the finished dish.","grammar:4696:ex2:words:0:zh":"Thick","grammar:4696:ex2:words:0:note":"あつい","grammar:4696:ex2:words:0:pos":"i-adjective","grammar:4696:ex2:words:1:zh":"meat","grammar:4696:ex2:words:1:note":"にく","grammar:4696:ex2:words:1:pos":"noun","grammar:4696:ex2:words:2:zh":"(the item being added)","grammar:4696:ex2:words:2:pos":"particle","grammar:4696:ex2:words:3:zh":"put in; add","grammar:4696:ex2:words:3:note":"いれ","grammar:4696:ex2:words:3:pos":"verb","grammar:4696:ex2:words:4:zh":"(addition completed)","grammar:4696:ex2:words:4:pos":"auxiliary verb","grammar:4696:ex2:words:5:zh":"soup","grammar:4696:ex2:words:5:pos":"noun","grammar:4696:ex2:words:6:zh":"(the thing being made)","grammar:4696:ex2:words:6:pos":"particle","grammar:4696:ex2:words:7:zh":"make; cook","grammar:4696:ex2:words:7:note":"つくり","grammar:4696:ex2:words:7:pos":"verb","grammar:4696:ex2:words:8:zh":"(polite tone)","grammar:4696:ex2:words:8:pos":"auxiliary verb","grammar:4696:ex2:points:0":"The entire phrase 「厚い肉を入れた」 modifies 「スープ」, meaning soup with thick pieces of meat added.","grammar:4696:ex2:points:1":"The ta-form modifying a noun can describe a characteristic of the finished result; it does not necessarily mean the whole sentence takes place in the past.","grammar:4696:ex2:points:2":"「厚い」 refers to thickness, unlike the homophone 「熱い」, which refers to a high temperature.","grammar:4696:ex3:trans":"His fingers are thick.","grammar:4696:ex3:structure":"〔彼の指〕＋は＋い-adjective＋です。","grammar:4696:ex3:words:0:zh":"he","grammar:4696:ex3:words:0:note":"かれ","grammar:4696:ex3:words:0:pos":"pronoun","grammar:4696:ex3:words:1:zh":"'s","grammar:4696:ex3:words:1:pos":"particle","grammar:4696:ex3:words:2:zh":"fingers","grammar:4696:ex3:words:2:note":"ゆび","grammar:4696:ex3:words:2:pos":"noun","grammar:4696:ex3:words:3:zh":"(topic marker)","grammar:4696:ex3:words:3:pos":"particle","grammar:4696:ex3:words:4:zh":"thick","grammar:4696:ex3:words:4:note":"あつい","grammar:4696:ex3:words:4:pos":"adjective","grammar:4696:ex3:words:5:zh":"(polite form)","grammar:4696:ex3:words:5:pos":"copula","grammar:4696:ex3:points:0":"厚い：thick (of fingers, etc.)","grammar:4696:ex3:points:1":"彼の指：his fingers","grammar:4696:ex4:trans":"A thick coat is needed.","grammar:4696:ex4:structure":"〔厚いコート〕＋が＋必要です。","grammar:4696:ex4:words:0:zh":"Thick","grammar:4696:ex4:words:0:note":"あつい","grammar:4696:ex4:words:0:pos":"adjective","grammar:4696:ex4:words:1:zh":"coat","grammar:4696:ex4:words:1:note":"loanword: coat","grammar:4696:ex4:words:1:pos":"noun","grammar:4696:ex4:words:2:zh":"(nominative)","grammar:4696:ex4:words:2:pos":"particle","grammar:4696:ex4:words:3:zh":"necessary","grammar:4696:ex4:words:3:note":"ひつよう","grammar:4696:ex4:words:3:pos":"na-adjective","grammar:4696:ex4:words:4:zh":"(polite form)","grammar:4696:ex4:words:4:pos":"copula","grammar:4696:ex4:points:0":"厚いコート：a thick coat","grammar:4696:ex4:points:1":"〜が必要: to need…","grammar:4696:ex5:trans":"This wall is thick.","grammar:4696:ex5:structure":"この＋noun＋は＋i-adjective＋です。","grammar:4696:ex5:words:0:zh":"this","grammar:4696:ex5:words:0:pos":"pre-noun adjectival","grammar:4696:ex5:words:1:zh":"wall","grammar:4696:ex5:words:1:note":"かべ","grammar:4696:ex5:words:1:pos":"noun","grammar:4696:ex5:words:2:zh":"(topic marker)","grammar:4696:ex5:words:2:pos":"particle","grammar:4696:ex5:words:3:zh":"Thick","grammar:4696:ex5:words:3:note":"あつい","grammar:4696:ex5:words:3:pos":"adjective","grammar:4696:ex5:words:4:zh":"(polite form)","grammar:4696:ex5:words:4:pos":"copula","grammar:4696:ex5:points:0":"厚い：thick","grammar:4696:ex5:points:1":"この壁: this wall"},"4697":{"example:4697:exzh":"Men and women should be equal.","example:4697:exzh2":"This event is open to men and women alike.","example:4697:exzh3":"I think friendship between men and women is possible.","example:4697:exzh4":"It's important to respect the opinions of both men and women.","example:4697:exzh5":"A society where men and women cooperate is ideal."},"4698":{"example:4698:exzh":"I fell in love with her at first sight.","example:4698:exzh2":"I liked it at first glance.","example:4698:exzh3":"I took one look at the painting, and it left an impression on me.","example:4698:exzh4":"He recognized me at a glance.","example:4698:exzh5":"A design you understand at a glance."},"4699":{"example:4699:exzh":"I'm planning to go on a trip next month.","example:4699:exzh2":"Next month looks like it'll be busy.","example:4699:exzh3":"Please don't forget next month's meeting.","example:4699:exzh4":"My birthday next month is a special day.","example:4699:exzh5":"A friend is coming over next month.","grammar:4699:ex:trans":"I am scheduled to go on a trip next month.","grammar:4699:ex:structure":"time, nounに＋〔行く＋予定〕＋です。「〜予定です」＝be scheduled to….","grammar:4699:ex:explain":"The key pattern is 「〜予定です」, meaning “be scheduled to” or “plan to.” It follows a verb in the dictionary form. 「旅行に行く予定」 means “be scheduled to go on a trip,” and sounds more objective than 「つもり」, like an already arranged itinerary. The 「に」 in 「旅行に行く」 marks purpose: “go on a trip.” The initial 「来月」 is a time noun used adverbially and can appear without a particle. The whole sentence means “I am scheduled to go on a trip next month.” The focus is the sense of a fixed arrangement expressed by 「〜予定です」, which differs slightly from 「つもり」, which expresses a personal intention.","grammar:4699:ex:words:0:zh":"next month","grammar:4699:ex:words:0:note":"らいげつ","grammar:4699:ex:words:0:pos":"noun","grammar:4699:ex:words:1:zh":"travel / trip","grammar:4699:ex:words:1:note":"りょこう","grammar:4699:ex:words:1:pos":"noun","grammar:4699:ex:words:2:zh":"(purpose)","grammar:4699:ex:words:2:pos":"particle","grammar:4699:ex:words:3:zh":"go","grammar:4699:ex:words:3:note":"いく；dictionary form","grammar:4699:ex:words:3:pos":"verb","grammar:4699:ex:words:4:zh":"plan","grammar:4699:ex:words:4:note":"よてい","grammar:4699:ex:words:4:pos":"noun","grammar:4699:ex:words:5:zh":"(polite form)","grammar:4699:ex:words:5:pos":"copula","grammar:4699:ex:points:0":"〜予定です: plan to / be scheduled to…","grammar:4699:ex:points:1":"旅行に行く: to go on a trip","grammar:4699:ex2:trans":"It looks like next month will get busy.","grammar:4699:ex2:structure":"timeは＋〔忙しくなりそう〕＋です。「〜なりそう」＝look likely to become… (based on appearances).","grammar:4699:ex2:words:0:zh":"next month","grammar:4699:ex2:words:0:note":"らいげつ","grammar:4699:ex2:words:0:pos":"noun","grammar:4699:ex2:words:1:zh":"(topic marker)","grammar:4699:ex2:words:1:pos":"particle","grammar:4699:ex2:words:2:zh":"Busily","grammar:4699:ex2:words:2:note":"いそがしく; continuative form","grammar:4699:ex2:words:2:pos":"adjective","grammar:4699:ex2:words:3:zh":"Looks likely to become","grammar:4699:ex2:words:3:note":"〜そう: based on appearances","grammar:4699:ex2:words:3:pos":"verb","grammar:4699:ex2:words:4:zh":"(polite form)","grammar:4699:ex2:words:4:pos":"copula","grammar:4699:ex2:points:0":"Verb masu-form stem＋そう: looks/seems… (なりそう＝looks likely to become)","grammar:4699:ex2:points:1":"忙しくなる: become busy","grammar:4699:ex3:trans":"Please do not forget next month’s meeting.","grammar:4699:ex3:structure":"〔来月の会議〕＋を＋〜ないでください。「〜ないでください」＝please do not….","grammar:4699:ex3:words:0:zh":"next month","grammar:4699:ex3:words:0:note":"らいげつ","grammar:4699:ex3:words:0:pos":"noun","grammar:4699:ex3:words:1:zh":"'s","grammar:4699:ex3:words:1:pos":"particle","grammar:4699:ex3:words:2:zh":"meeting","grammar:4699:ex3:words:2:note":"かいぎ","grammar:4699:ex3:words:2:pos":"noun","grammar:4699:ex3:words:3:zh":"(object marker)","grammar:4699:ex3:words:3:pos":"particle","grammar:4699:ex3:words:4:zh":"don't forget","grammar:4699:ex3:words:4:note":"〜ないで","grammar:4699:ex3:words:4:pos":"verb","grammar:4699:ex3:words:5:zh":"please","grammar:4699:ex3:words:5:note":"〜ないでください","grammar:4699:ex3:words:5:pos":"verb","grammar:4699:ex3:points:0":"〜ないでください: please don't…","grammar:4699:ex3:points:1":"来月の会議: next month’s meeting","grammar:4699:ex4:trans":"The birthday next month is a special day.","grammar:4699:ex4:structure":"〔来月の誕生日〕＋は＋〔特別な日〕＋です。","grammar:4699:ex4:words:0:zh":"next month","grammar:4699:ex4:words:0:note":"らいげつ","grammar:4699:ex4:words:0:pos":"noun","grammar:4699:ex4:words:1:zh":"'s","grammar:4699:ex4:words:1:pos":"particle","grammar:4699:ex4:words:2:zh":"birthday","grammar:4699:ex4:words:2:note":"たんじょうび","grammar:4699:ex4:words:2:pos":"noun","grammar:4699:ex4:words:3:zh":"(topic marker)","grammar:4699:ex4:words:3:pos":"particle","grammar:4699:ex4:words:4:zh":"special","grammar:4699:ex4:words:4:note":"とくべつ","grammar:4699:ex4:words:4:pos":"na-adjective","grammar:4699:ex4:words:5:zh":"day","grammar:4699:ex4:words:5:note":"ひ","grammar:4699:ex4:words:5:pos":"noun","grammar:4699:ex4:words:6:zh":"is","grammar:4699:ex4:words:6:pos":"copula","grammar:4699:ex4:points:0":"特別な日: a special day","grammar:4699:ex4:points:1":"来月の誕生日: the birthday next month","grammar:4699:ex5:trans":"A friend is coming over to my house next month.","grammar:4699:ex5:structure":"time, nounが＋〔遊びに〕＋来ます。「遊びに来る」＝come over for a visit.","grammar:4699:ex5:words:0:zh":"next month","grammar:4699:ex5:words:0:note":"らいげつ","grammar:4699:ex5:words:0:pos":"noun","grammar:4699:ex5:words:1:zh":"friend","grammar:4699:ex5:words:1:note":"ともだち","grammar:4699:ex5:words:1:pos":"noun","grammar:4699:ex5:words:2:zh":"(nominative)","grammar:4699:ex5:words:2:pos":"particle","grammar:4699:ex5:words:3:zh":"to play (come to…)","grammar:4699:ex5:words:3:note":"masu-stem + に","grammar:4699:ex5:words:3:pos":"verb","grammar:4699:ex5:words:4:zh":"(purpose)","grammar:4699:ex5:words:4:pos":"particle","grammar:4699:ex5:words:5:zh":"come","grammar:4699:ex5:words:5:note":"きます","grammar:4699:ex5:words:5:pos":"verb","grammar:4699:ex5:points:0":"遊びに来る: come over for a visit","grammar:4699:ex5:points:1":"友達が: a friend (が marks new information)","exam:4699:zh":"This month is May, so the trip in June is scheduled for next month.","exam:4699:why":"From May, June is 「来月」. 「今月」 in this context means May."}};